insert:
property bool modYearList: controller && controller.screenID === "ArtistAlbumList"
property int modSavedBoundsBehavior: -1
function modApplyBounds() {
  if (typeof listView === "undefined" || !listView) return
  if (modYearList) {
    if (modSavedBoundsBehavior < 0) modSavedBoundsBehavior = listView.boundsBehavior
    listView.boundsBehavior = Flickable.StopAtBounds
  } else if (modSavedBoundsBehavior >= 0) {
    listView.boundsBehavior = modSavedBoundsBehavior
    modSavedBoundsBehavior = -1
  }
}
onModYearListChanged: modApplyBounds()
Component.onCompleted: modApplyBounds()

function modYear(primary,secondary){
  var id=Number(primary)
  if(!isFinite(id) || id<=2164260864 || id>2181038079)id=Number(secondary)
  return modYearList?Years.year(screen.title,id):""
}

// Chronological album lists use one passive indicator at every list length.
// Do not instantiate Sony's long-list drag bar in this mode: it switches
// from a thin indicator to a wide thumb after scrolling starts.
Loader {
  objectName: "nativeAlbumScrollLoader"

  active: !screen.modYearList
  sourceComponent: Component {
    SCmnScrollBarForContentsList {
      anchors.fill: parent
      flickable: listView
      initial_char_list: screen.initial_char_list
      balloonShow: true
      isAllRowExists: screen.isAllRowExists
    }
  }
}
Item {
  id: yearScrollTrack
  objectName: "albumYearScrollTrack"
  anchors { top: listView.top; bottom: listView.bottom; right: listView.right; rightMargin: 5 }
  width: 3
  enabled: false
  clip: true
  property real ratio: isFinite(listView.visibleArea.heightRatio) ? listView.visibleArea.heightRatio : 0
  visible: screen.modYearList && screen.visible && listView.count > 0 && height > 0 && ratio > 0 && ratio < 1
  Rectangle {
    objectName: "albumYearScrollThumb"
    width: parent.width
    height: Math.min(parent.height, Math.max(20, parent.height * parent.ratio))
    y: Math.max(0, Math.min(parent.height-height, parent.height * (isFinite(listView.visibleArea.yPosition) ? listView.visibleArea.yPosition : 0)))
    color: viewstyle.textcolor.L1
  }
